#define SYS_mmap2 192

// Calculate offset in 4KB pages (e.g., 2MB / 4096 = 512)
unsigned long page_offset = 512; 
int fd = 3;
size_t length = 4096 * 4;

// Invocation via low-level syscall
void* addr = (void*) syscall(
    SYS_mmap2, 
    0,                  // Recommended address (NULL)
    length,             // Length in bytes
    PROT_READ | PROT_WRITE, 
    MAP_SHARED, 
    (unsigned long) fd, 
    page_offset         // <-- Offset in 4096-byte units
);

if (addr == (void*)-1L) { /* handle failure */ }
